<?php require_once '../../includes/auth.php';$msg='If the email exists, a reset link has been generated.';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$s=db()->prepare('SELECT id FROM users WHERE email=?');$s->execute([trim($_POST['email'])]);if($u=$s->fetch()){$t=bin2hex(random_bytes(32));db()->prepare('INSERT INTO password_resets(user_id,token_hash,expires_at) VALUES(?,?,?)')->execute([$u['id'],hash('sha256',$t),date('Y-m-d H:i:s',time()+30)]);$msg.=' Demo link: <a href="reset.php?token='.$t.'">Reset password</a>';}}$title='Password reset';include '../../includes/header.php';?><div class="card"><h1>Forgot password</h1><p><?=$msg?></p><form method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="email" name="email" required><button>Request link</button></form></div><?php include '../../includes/footer.php';
